) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `properties`;
CREATE TABLE `properties` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `landowner_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ward` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `landmark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `google_maps_pin` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `width_ft` decimal(10,2) DEFAULT NULL,
  `length_ft` decimal(10,2) DEFAULT NULL,
  `facing` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_corner_plot` tinyint(1) NOT NULL DEFAULT '0',
  `facings` json DEFAULT NULL,
  `road_width_ft` decimal(10,2) DEFAULT NULL,
  `khatha_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `e_khatha_status` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tax_paid` tinyint(1) NOT NULL DEFAULT '0',
  `pid_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `latitude` float DEFAULT NULL,
  `longitude` float DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_properties_landowner_id` (`landowner_id`),
  KEY `idx_properties_pid_number` (`pid_number`),
  CONSTRAINT `fk_properties_landowner_id` FOREIGN KEY (`landowner_id`) REFERENCES `landowner_profiles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `reconstruction_work_types`;
CREATE TABLE `reconstruction_work_types` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `professional_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `work_type` enum('MAJOR_RECONSTRUCTION','MINOR_REPAIR_MAINTENANCE','PAINTING_FINISHING','CUSTOM') COLLATE utf8mb4_unicode_ci NOT NULL,
  `custom_description` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_reconstruction_work_types_professional_id` (`professional_id`),
  KEY `idx_reconstruction_work_types_work_type` (`work_type`),
  CONSTRAINT `fk_reconstruction_work_types_professional_id` FOREIGN KEY (`professional_id`) REFERENCES `professional_profiles` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `support_articles`;
CREATE TABLE `support_articles` (
  `id` varchar(32) NOT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `audience` varchar(20) NOT NULL DEFAULT 'all',
  `category` varchar(50) NOT NULL DEFAULT 'general',
  `keywords` json NOT NULL,
  `content_md` text NOT NULL,
  `steps_json` json DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ix_support_articles_slug` (`slug`),
  KEY `ix_support_articles_title` (`title`),
  KEY `ix_support_articles_audience` (`audience`),
  KEY `ix_support_articles_active` (`active`),
  KEY `ix_support_articles_category` (`category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `support_flows`;
CREATE TABLE `support_flows` (
  `id` varchar(32) NOT NULL,
  `name` varchar(255) NOT NULL,
  `audience` varchar(20) NOT NULL DEFAULT 'all',
  `trigger_keywords` json NOT NULL,
  `nodes_json` json NOT NULL,
  `active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `ix_support_flows_name` (`name`),
  KEY `ix_support_flows_audience` (`audience`),
  KEY `ix_support_flows_active` (`active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `support_tickets`;
CREATE TABLE `support_tickets` (
  `id` varchar(32) NOT NULL,
  `user_id` varchar(36) DEFAULT NULL,
  `role` varchar(20) DEFAULT NULL,
  `route` varchar(255) DEFAULT NULL,
  `subject` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'open',
  `metadata_json` json DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `assigned_to` varchar(36) DEFAULT NULL,
  `admin_notes` text,
  PRIMARY KEY (`id`),
  KEY `ix_support_tickets_route` (`route`),
  KEY `ix_support_tickets_status` (`status`),
  KEY `ix_support_tickets_subject` (`subject`),
  KEY `ix_support_tickets_role` (`role`),
  KEY `ix_support_tickets_user_id` (`user_id`),
  KEY `ix_support_tickets_assigned_to` (`assigned_to`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `transactions`;
CREATE TABLE `transactions` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `project_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `transaction_type` enum('PID_VERIFICATION','FEASIBILITY_UNLOCK','PRIORITY_LISTING') COLLATE utf8mb4_unicode_ci NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `currency` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INR',
  `razorpay_order_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `razorpay_payment_id` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `razorpay_signature` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('PENDING','SUCCESS','FAILED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `match_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `admin_resolution_status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `admin_notes` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `razorpay_order_id` (`razorpay_order_id`),
  UNIQUE KEY `razorpay_payment_id` (`razorpay_payment_id`),
  KEY `idx_transactions_user_id` (`user_id`),
  KEY `idx_transactions_project_id` (`project_id`),
  KEY `idx_transactions_transaction_type` (`transaction_type`),
  KEY `idx_transactions_status` (`status`),
  KEY `idx_transactions_razorpay_order_id` (`razorpay_order_id`),
  KEY `idx_transactions_razorpay_payment_id` (`razorpay_payment_id`),
  KEY `ix_transactions_match_id` (`match_id`),
  KEY `ix_transactions_admin_resolution_status` (`admin_resolution_status`),
  CONSTRAINT `fk_transactions_project_id` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_transactions_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'User',
  `hashed_password` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `role` enum('LANDOWNER','PROFESSIONAL','ADMIN') COLLATE utf8mb4_unicode_ci NOT NULL,
  `is_active` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'false',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `avatar_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  KEY `idx_users_email` (`email`),
  KEY `idx_users_role` (`role`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

